function bakeBatches(trays, days) {
    function daysNeeded(capacity) {
        let count = 1;
        let load = 0;
        for (const tray of trays) {
            if (load + tray > capacity) {
                count++;
                load = 0;
            }
            load += tray;
        }
        return count;
    }
    let capacity = Math.max(...trays);
    while (daysNeeded(capacity) > days)
        capacity++;
    return capacity;
}

function bakeBatches(trays, days) {
    function daysNeeded(capacity) {
        let count = 1;
        let load = 0;
        for (const tray of trays) {
            if (load + tray > capacity) {
                count++;
                load = 0;
            }
            load += tray;
        }
        return count;
    }
    let low = Math.max(...trays);
    let high = trays.reduce((sum, tray) => sum + tray, 0);
    while (low < high) {
        const middle = Math.floor((low + high) / 2);
        if (daysNeeded(middle) <= days)
            high = middle;
        else
            low = middle + 1;
    }
    return low;
}
